"use server";

import { prisma } from "@formbricks/database";
import { AuthenticationError, AuthorizationError } from "@formbricks/types/errors";
import { getUser } from "@/lib/user/service";
import { authenticatedActionClient } from "@/lib/utils/action-client";

export interface TOrganizationMembership {
  name: string;
  role: string;
}

interface DownloadMyDataResult {
  name: string;
  email: string;
  locale: string;
  notificationSettings: Record<string, unknown> | null;
  organizationMemberships: TOrganizationMembership[];
}

export const downloadMyDataAction = authenticatedActionClient.action(
  async ({ ctx }) => {
    const user = await getUser(ctx.user.id);
    if (!user) {
      throw new AuthorizationError("User not found");
    }

    const memberships = await prisma.membership.findMany({
      where: {
        userId: ctx.user.id,
      },
      select: {
        role: true,
        organization: {
          select: {
            name: true,
          },
        },
      },
    });

    const organizationMemberships: TOrganizationMembership[] = memberships.map((m) => ({
      name: m.organization.name,
      role: m.role,
    }));

    const result: DownloadMyDataResult = {
      name: user.name,
      email: user.email,
      locale: user.locale,
      notificationSettings: user.notificationSettings,
      organizationMemberships,
    };

    return { data: result };
  }
);

import { formatDateTimeForDisplay } from "@/lib/utils/datetime";
import { SettingsCard } from "@/app/(app)/workspaces/[workspaceId]/settings/components/SettingsCard";
import { DownloadMyDataButton } from "@/app/(app)/account/settings/profile/components/DownloadMyDataButton";
import { H4, Small } from "@/modules/ui/components/typography";
import { useTranslation } from "react-i18next";

interface AccountActivityProps {
  createdAt: Date;
  lastLoginAt: Date | null | undefined;
  locale: string;
}

export const AccountActivity = ({ createdAt, lastLoginAt, locale }: AccountActivityProps) => {
  const { t } = useTranslation();

  return (
    <SettingsCard
      title={t("workspace.settings.profile.account_activity")}
      description={t("workspace.settings.profile.account_activity_description")}>
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <Small color="muted">{t("workspace.settings.profile.account_created")}</Small>
          <Small>
            {formatDateTimeForDisplay(createdAt, locale)}
          </Small>
        </div>
        <div className="flex items-center justify-between">
          <Small color="muted">{t("workspace.settings.profile.last_login")}</Small>
          <Small>
            {lastLoginAt ? formatDateTimeForDisplay(lastLoginAt, locale) : t("workspace.settings.profile.never_logged_in")}
          </Small>
        </div>
        <div className="pt-2">
          <DownloadMyDataButton />
        </div>
      </div>
    </SettingsCard>
  );
};

